# -*- coding: utf-8 -*-
# (speaker, italian, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
F, L, MT, S, E, C = "Filippo", "Lorenzo", "Matteo", "Sandro", "Ferretti", "Chiara"
D = [
("#", "Scena 1 — Venerdì 20 giugno, ore 7.30. Il piazzale di carico della Pelletteria Corsini, Scandicci.", "장면 1 — 6월 20일 금요일 오전 7시 30분. 스칸디치, 코르시니 공방의 하역장."),
(None, "Il sole è già alto. Un camion bianco con la scritta di uno spedizioniere francese aspetta con il portellone aperto. Sulle pedane, scatole nere tutte uguali, senza nessun nome. Filippo, in maniche di camicia, ha in mano un elenco. Lorenzo conta i bancali ad alta voce.", "해가 벌써 높다. 프랑스 운송회사 이름이 적힌 흰 트럭이 짐칸 문을 연 채 기다리고 있다. 팔레트 위에는 이름 하나 없는 똑같은 검은 상자들. 와이셔츠 바람의 필리포가 목록을 들고 있다. 로렌초가 팔레트를 소리 내어 센다."),
(L, "Ventotto, ventinove, trenta. Trenta bancali, cento borse ciascuno. Tremila.", "스물여덟, 스물아홉, 서른. 서른 팔레트, 팔레트마다 백 개. 3,000개."),
(F, "Tremila. Neanche una di meno. Neanche un giorno di ritardo.", "3,000개. 하나도 모자라지 않게. 하루도 늦지 않게."),
(L, "Diciannove anni e mezzo senza un ritardo, adesso. Se lo sapesse Hélène, ci manderebbe i fiori.", "이제 19년 반 동안 지연 한 번 없는 거네요. 엘렌이 알면 꽃이라도 보내겠어요."),
(F, "Hélène lo sa. È per questo che a febbraio non ci ha tagliato il quaranta. Hai preparato la fattura?", "엘렌은 알아. 그래서 2월에 40퍼센트를 안 잘랐지. 송장은 준비했어?"),
(L, "Pronta. Tremila pezzi a duecentosettantuno euro e sessanta. Ottocentoquattordicimila e ottocento euro.", "준비됐어요. 3,000개, 개당 271유로 60센트. 81만 4,800유로."),
(F, "E li vedremo a fine settembre. Novanta giorni fine mese. Come sempre.", "그리고 그 돈은 9월 말에나 보겠지. 월말 마감 90일. 늘 그렇듯이."),
(L, "Come sempre. Intanto paghiamo stipendi, luce e pelle.", "늘 그렇듯이요. 그동안 우린 월급, 전기료, 가죽값을 내고요."),
(F, "Lo so. Per questo la mamma dice che il conto terzi è una mucca che fa il latte tre mesi dopo.", "알아. 그래서 엄마가 위탁 생산은 석 달 뒤에 젖이 나오는 소라고 하시잖아."),
(L, "Sua madre ha sempre una mucca o un proverbio. Di solito tutti e due.", "어머님은 늘 소 아니면 속담이 있으시죠. 보통은 둘 다고요."),
(F, "E di solito hanno ragione tutti e due. Il foglio di Matteo per luglio l'hai visto?", "그리고 보통은 둘 다 맞지. 7월분 마테오 한 장 보고서 봤어?"),
(L, "Visto. Vendite del marchio in crescita, cassa in calo. Senza aggettivi, come vuole Lei.", "봤어요. 브랜드 매출은 늘고, 현금은 줄고. 사장님 원하시는 대로 형용사 없이요."),
(None, "Una Vespa entra nel piazzale e si ferma di traverso. Matteo si toglie il casco con il telefono già in mano.", "베스파 한 대가 하역장으로 들어와 비스듬히 멈춘다. 마테오가 휴대폰을 손에 든 채 헬멧을 벗는다."),
(MT, "Buongiorno. Avete visto la mail di Sandro?", "안녕. 산드로 메일 봤어?"),
(F, "Alle sette e mezzo non leggo le mail. Carico camion.", "아침 7시 반엔 메일 안 읽어. 트럭에 짐 싣지."),
(MT, "Allora te la leggo io. « Caro Matteo, per l'ordine d'autunno ho bisogno del cinquanta per cento di anticipo alla conferma. Altrimenti non riesco a tenervi il lotto. Mi dispiace. Sandro. »", "그럼 내가 읽어 줄게. '마테오에게, 가을 주문은 확정할 때 선금 50퍼센트가 필요해. 안 그러면 로트를 붙잡아 둘 수가 없어. 미안하다. 산드로.'"),
(F, "Il cinquanta? A gennaio ti aveva promesso pagamento a sessanta giorni sopra i duecento pellami.", "50이라고? 1월엔 피혁 200장 넘으면 60일 결제라고 약속했잖아."),
(MT, "Lo so. Gliel'ho scritto. Mi ha risposto con una riga: « A gennaio il mondo era un altro. »", "알아. 그렇게 써 보냈어. 한 줄로 답이 왔어. '1월엔 세상이 달랐지.'"),
(L, "Di quanti pellami parliamo?", "피혁이 몇 장이에요?"),
(MT, "Trecento. Ventidue piedi in media, a sei e ottanta il piede. Sono quarantaquattromila ottocentottanta euro. La metà fa ventiduemila quattrocentoquaranta.", "300장. 평균 22평방피트, 평방피트당 6.80유로. 4만 4,880유로. 절반이면 2만 2,440유로."),
(F, "Sei e ottanta? Non era sei e venti?", "6.80? 6.20 아니었어?"),
(MT, "Era. La pelle grezza è aumentata. E a maggio quella maison gli ha comprato tutto il miele e tutta la crema, pagando in contanti. Per questo abbiamo dovuto passare al naturale.", "그랬지. 원피 값이 올랐어. 그리고 5월에 그 메종이 꿀색이랑 크림을 현금으로 몽땅 사 갔잖아. 그래서 우리가 내추럴로 바꿔야 했던 거고."),
(F, "E adesso vuole i nostri contanti per compensare quelli che non ha più.", "그러니까 이제 자기한테 없는 현금을 우리 현금으로 메우겠다는 거네."),
(MT, "Vuole essere sicuro che paghiamo. È diverso.", "우리가 돈을 낸다는 확신을 원하는 거야. 그건 달라."),
(F, "Per me è uguale. Lorenzo, quanto abbiamo sul conto stamattina?", "나한텐 똑같아. 로렌초, 오늘 아침 통장에 얼마 있어?"),
(L, "Poco. Gli stipendi di giugno escono il ventisette. Il fido è usato per un milione e sette. Ventiduemila li troviamo, ma non senza toccare qualcosa.", "별로 없어요. 6월 월급이 27일에 나가요. 당좌대월은 170만 유로 쓰고 있고요. 2만 2천은 구할 수 있지만, 뭔가를 건드리지 않고는 안 돼요."),
(F, "Allora andiamo da Sandro. Oggi. Di persona.", "그럼 산드로한테 가자. 오늘. 직접."),
(MT, "Vieni anche tu?", "형도 가?"),
(F, "Sì. Le cose che si scrivono alle sette di sera si cambiano alle dieci di mattina, guardandosi in faccia. Lorenzo, alle tre fissami la Ferretti.", "응. 저녁 7시에 쓴 건 아침 10시에 얼굴 보고 바꾸는 거야. 로렌초, 3시에 페레티 약속 잡아 줘."),
(L, "La Ferretti di venerdì pomeriggio? Ci provo.", "금요일 오후에 페레티를요? 해 볼게요."),
(F, "Provaci. E dille che porto i numeri, non le scuse.", "해 봐. 그리고 변명이 아니라 숫자를 들고 간다고 전해."),
(None, "L'autista francese chiude il portellone e fa un cenno con la mano. Il camion esce lentamente dal cancello. Filippo lo guarda finché non sparisce dietro la curva.", "프랑스인 기사가 짐칸 문을 닫고 손짓을 한다. 트럭이 천천히 정문을 빠져나간다. 필리포는 트럭이 모퉁이 뒤로 사라질 때까지 지켜본다."),

("#", "Scena 2 — Ore 10. Conceria Bini, Santa Croce sull'Arno.", "장면 2 — 오전 10시. 산타크로체 술라르노, 비니 무두질 공장."),
(None, "Il rumore dei bottali che girano. Un odore forte di tannino e di legno bagnato. Sandro Bini, grembiule di cuoio e stivali di gomma, li riceve in un piccolo ufficio con la finestra sul magazzino.", "드럼통 돌아가는 소리. 타닌과 젖은 나무 냄새가 짙다. 가죽 앞치마에 고무장화 차림의 산드로 비니가 창고가 내려다보이는 작은 사무실에서 그들을 맞는다."),
(S, "O guarda chi c'è. Il direttore in persona. Un l'avevo mai visto qui da me, il fratello grande.", "어이, 누가 왔나 봐. 사장님이 직접 오셨네. 형님은 우리 공장에서 한 번도 못 봤는데."),
(F, "Buongiorno, signor Bini. La Maison compra la pelle da sola, lo sa. Io venivo poco.", "안녕하세요, 비니 씨. 메종은 가죽을 직접 사잖아요. 그래서 제가 잘 안 왔죠."),
(S, "E ora viene perché c'è da parlare di soldi. Mi garba la gente che viene quando c'è da parlare di soldi. Caffè?", "그런데 이제 돈 얘기가 있으니 오신 거고. 난 돈 얘기할 때 직접 오는 사람이 좋아. 커피?"),
(MT, "Volentieri. Sandro, la tua mail ci ha preso un po' alla sprovvista.", "좋지. 산드로, 네 메일에 우리가 좀 당황했어."),
(S, "Lo so, bimbo. E un mi piace nemmeno a me scriverle, certe mail. Ma te lo spiego con i numeri, che è meglio.", "알아, 얘야. 나도 그런 메일 쓰는 거 싫어. 근데 숫자로 설명하는 게 낫겠다."),
(F, "Ci farebbe un piacere.", "그래 주시면 고맙겠어요."),
(S, "La pelle grezza, da gennaio, m'è aumentata del quindici per cento. I macelli vogliono essere pagati subito. La mia banca, a marzo, m'ha ridotto il fido. E a maggio una maison che conoscete m'ha comprato tutto il miele e tutta la crema, in contanti, in un giorno.", "원피 값이 1월부터 15퍼센트 올랐어. 도축장은 바로 돈 달라고 하지. 내 은행은 3월에 당좌대월을 줄였고. 그리고 5월엔 너희도 아는 어떤 메종이 꿀색이랑 크림을 하루 만에 현금으로 몽땅 사 갔어."),
(MT, "E noi siamo rimasti con il naturale.", "그래서 우리한텐 내추럴만 남았고."),
(S, "Il naturale è bello, eh. Invecchia meglio di tutti. Ma io, per comprare il grezzo per voi, devo anticipare io. E per anticipare, mi servono i vostri soldi prima, un dopo.", "내추럴도 예뻐. 제일 곱게 늙지. 근데 너희 줄 원피를 사려면 내가 먼저 돈을 내야 해. 그리고 먼저 내려면 너희 돈이 나중이 아니라 먼저 필요하고."),
(F, "Capisco. Per quanto la capisca, però, il cinquanta per cento per noi è tanto. Il quaranta?", "이해합니다. 하지만 아무리 이해한다 해도, 50퍼센트는 저희한테 많아요. 40은요?"),
(S, "Il quaranta un mi basta, dottore. Sono costretto a chiedere il cinquanta. Se un fossi costretto, un ve lo chiederei.", "40으론 안 돼요, 사장님. 50을 달라고 할 수밖에 없어요. 어쩔 수 없는 게 아니면 이런 말 안 하지."),
(MT, "Allora diamo al cinquanta qualcosa in cambio. Il lotto tenuto da parte per noi, con il nostro nome sopra.", "그럼 50에 뭔가를 붙여 줘. 우리 이름 붙여서 따로 빼 둔 로트."),
(S, "Questo sì. Il lotto ve lo segno col gesso stamani stesso.", "그건 되지. 로트는 오늘 아침에 바로 분필로 표시해 둘게."),
(F, "E il prezzo. Sei e ottanta fermo fino a dicembre, qualunque cosa succeda al grezzo.", "그리고 가격. 원피 값이 어떻게 되든 12월까지 6.80 고정."),
(S, "(si gratta la testa) Fino a dicembre... Va bene. Fino a dicembre.", "(머리를 긁으며) 12월까지라... 좋아. 12월까지."),
(MT, "E la consegna in tre settimane. Il colore « dopo la pioggia » per la Corea ci serve entro metà luglio, se vogliamo fare i prototipi.", "그리고 납품은 3주 안에. 한국용 '비 갠 뒤' 색은 시제품 만들려면 7월 중순까지 있어야 해."),
(S, "Il grigio verde? Quello è un colore che m'ha fatto sudare. Ce la faccio. Tre settimane.", "그 회녹색? 그거 땀 좀 뺀 색이야. 할 수 있어. 3주."),
(MT, "Ce lo fai vedere?", "보여 줄 수 있어?"),
(S, "Venite. Ma guardate dove mettete i piedi, che qui per terra c'è più acqua che in Arno.", "와 봐. 근데 발밑 조심해. 여기 바닥엔 아르노강보다 물이 많으니까."),
(None, "Sandro li porta tra i bottali. Da una pila di pelli tira fuori un ritaglio grigio con un riflesso verde, come una strada bagnata.", "산드로가 둘을 드럼통 사이로 데려간다. 가죽 더미에서 젖은 길처럼 초록빛이 도는 회색 자투리를 꺼낸다."),
(F, "È questo? Sembra... sembra davvero l'asfalto dopo un temporale.", "이거예요? 정말... 소나기 지나간 뒤 아스팔트 같네요."),
(S, "L'ha chiamato così la vostra signora coreana, mi dice il su' fratello. « Dopo la pioggia ». Io lo chiamo « il disperato », perché m'ha fatto disperare tre settimane.", "그쪽 한국 손님이 그렇게 이름 붙였다던데, 동생 말로는. '비 갠 뒤.' 난 '절망'이라고 불러. 3주 동안 날 절망하게 했거든."),
(MT, "In Corea mettiamo il nome di lei. Il tuo lo teniamo per noi.", "한국에선 그분이 붙인 이름을 쓰자. 네가 붙인 건 우리끼리 쓰고."),
(S, "Bravo. E ditele che invecchia diverso dal miele: diventa più scuro sui bordi, come le nuvole.", "그래. 그리고 그분한테 이건 꿀색이랑 다르게 늙는다고 말해 줘. 가장자리가 구름처럼 더 짙어진다고."),
(F, "Lo scriviamo sul cartellino. Mio fratello scrive bene, io conto.", "택에 쓸게요. 동생은 글을 잘 쓰고, 저는 계산을 하고요."),
(S, "(ride) Allora in famiglia siete messi bene. Uno scrive, uno conta, e la sorella disegna. Torniamo dentro, che di là si sente il telefono.", "(웃으며) 그럼 집안 구성이 좋네. 하나는 쓰고, 하나는 세고, 누이는 그리고. 안으로 돌아가자, 저쪽에서 전화 울린다."),
(F, "Allora, se ho capito bene: cinquanta per cento alla conferma, lotto riservato, prezzo fermo fino a dicembre, consegna in tre settimane.", "그럼 제가 제대로 이해했다면, 확정 때 50퍼센트, 로트 예약, 12월까지 가격 고정, 3주 안 납품."),
(S, "Ha capito bene. E il resto alla consegna, non a sessanta giorni. Per stavolta.", "제대로 이해했어요. 그리고 나머지는 60일 뒤가 아니라 납품 때. 이번만은."),
(F, "Per stavolta. (pausa) Signor Bini, posso farLe una domanda fuori dai numeri?", "이번만은. (잠시 침묵) 비니 씨, 숫자 말고 질문 하나 해도 될까요?"),
(S, "Dica.", "말해 봐요."),
(F, "Quella maison che ha comprato tutto in contanti... se tornasse domani con altri contanti, a chi darebbe la pelle?", "현금으로 몽땅 사 간 그 메종이요... 내일 또 현금을 들고 오면, 가죽을 누구한테 주시겠어요?"),
(S, "(lo guarda a lungo) A chi m'ha guardato in faccia quando un c'era bisogno. Il su' babbo veniva qui negli anni novanta, sa? Un comprava niente. Veniva a vedere.", "(한참 그를 바라보다) 필요 없을 때 내 얼굴 보러 온 사람한테. 당신 아버지가 90년대에 여기 왔었어요, 알아요? 아무것도 안 샀어. 그냥 보러 왔지."),
(F, "Non lo sapevo.", "몰랐어요."),
(S, "Ora lo sa. Si beve, 'sto caffè, o lo si guarda?", "이제 알았네. 그 커피 마실 거요, 쳐다볼 거요?"),

("#", "Scena 3 — Ore 15. Banca di Credito Fiorentino, ufficio della dottoressa Ferretti.", "장면 3 — 오후 3시. 피렌체 신용은행, 페레티 박사의 사무실."),
(None, "Aria condizionata troppo forte. Sulla scrivania della dottoressa Elisa Ferretti, il piano industriale consegnato a marzo, pieno di post-it gialli.", "에어컨이 너무 세다. 엘리사 페레티 박사의 책상 위에는 3월에 낸 사업계획서가 노란 포스트잇으로 가득하다."),
(E, "Dottor Corsini, un venerdì pomeriggio di giugno. Dev'essere urgente.", "코르시니 씨, 6월 금요일 오후라니. 급한 일인가 보네요."),
(F, "Urgente e piccolo, dottoressa. Ventiduemila euro.", "급하지만 작은 일입니다, 박사님. 2만 2천 유로요."),
(E, "Piccolo per un'azienda come la vostra. Ma il fido è al limite. Mi dica di che cosa si tratta.", "그쪽 같은 회사엔 작은 돈이죠. 하지만 당좌대월이 한도에 차 있어요. 무슨 일인지 말씀해 보세요."),
(MT, "Un anticipo alla conceria per la pelle del marchio. Ordini già confermati: la Corea, il Giappone, Amsterdam.", "브랜드용 가죽 대금을 무두질 공장에 선금으로 주는 거예요. 주문은 이미 확정됐어요. 한국, 일본, 암스테르담."),
(E, "E i pagamenti di quegli ordini quando arrivano?", "그 주문들 대금은 언제 들어오죠?"),
(MT, "Il Giappone ha pagato il trenta per cento a maggio e il saldo a luglio, dopo il controllo. La Corea a trenta giorni dalla consegna. La consegna d'autunno è a settembre.", "일본은 5월에 30퍼센트를 냈고 잔금은 7월, 검품 뒤에 들어와요. 한국은 납품 30일 뒤. 가을 납품은 9월이고요."),
(E, "Quindi soldi a ottobre. E la conceria li vuole a giugno.", "그러니까 돈은 10월에. 그런데 공장은 6월에 원하고."),
(MT, "Esatto. Il problema non è se arrivano. È quando.", "맞아요. 문제는 들어오느냐가 아니라 언제냐예요."),
(E, "Il problema delle aziende sane è sempre il quando, dottore. Quelle malate hanno il problema del se.", "건강한 회사의 문제는 늘 '언제'예요, 선생님. 아픈 회사의 문제가 '들어오느냐'고요."),
(F, "Esatto. Per questo ho una proposta. Stamattina è partita la consegna per la Maison. Tremila pezzi, ottocentoquattordicimila euro di fattura. Vorrei anticiparla.", "맞습니다. 그래서 제안이 있어요. 오늘 아침 메종 납품분이 출발했습니다. 3,000개, 송장 81만 4,800유로. 이걸 선지급받고 싶습니다."),
(E, "L'anticipo fatture lo avete già, fino a tre milioni. Possiamo arrivare all'ottanta per cento della fattura. Ma mi permetta di essere franca.", "매출채권 담보대출은 이미 300만 유로까지 있으시죠. 송장의 80퍼센트까지 가능해요. 하지만 솔직하게 말씀드려도 될까요?"),
(F, "Prego.", "그러세요."),
(E, "Lei mi sta chiedendo di usare i soldi della Maison per finanziare un marchio che, a marzo, nel suo piano, era « un esperimento con un tetto e una data di revisione ». Le parole sono sue.", "지금 메종의 돈으로, 3월 계획서에선 '상한과 점검 날짜가 있는 실험'이었던 브랜드를 지원하겠다는 거예요. 그 말은 사장님이 쓰신 거고요."),
(F, "Lo so. Le ho scritte io.", "압니다. 제가 썼죠."),
(MT, "Dottoressa, posso? L'esperimento, in tre mesi, ha venduto duecentoventi borse. Il Giappone ha pagato tutto. La Corea ha riordinato centoventi pezzi.", "박사님, 제가 말씀드려도 될까요? 그 실험이 석 달 동안 가방 220개를 팔았어요. 일본은 전액 냈고요. 한국은 120개를 재주문했어요."),
(E, "Bravo. Sono numeri veri. E piccoli. Ventiduemila oggi sono piccoli. Ventiduemila ogni due mesi non lo sono più.", "잘하셨네요. 진짜 숫자예요. 그리고 작은 숫자죠. 오늘 2만 2천은 작아요. 두 달마다 2만 2천이면 더는 작지 않고요."),
(F, "Per questo le chiedo di farlo come operazione separata. Una riga a sé, con una scadenza. Settembre.", "그래서 별도 거래로 해 달라는 겁니다. 따로 한 줄, 만기를 정해서. 9월로."),
(E, "Separata e con scadenza. In modo che, a settembre, si veda se il marchio si ripaga la sua pelle.", "별도로, 만기를 정해서. 9월에 브랜드가 자기 가죽값을 갚는지 보이도록."),
(F, "In modo che si veda. Esatto.", "보이도록. 정확합니다."),
(E, "E se a settembre non si vede?", "그런데 9월에 안 보이면요?"),
(F, "Allora a settembre ne parlo prima con la mia famiglia e poi con Lei. In quest'ordine.", "그럼 9월에 먼저 가족과 얘기하고, 그다음에 박사님과 얘기하겠습니다. 그 순서대로요."),
(E, "Mi piace quest'ordine. Le banche arrivano sempre dopo le madri, in Toscana.", "그 순서 마음에 드네요. 토스카나에선 은행은 늘 어머니들 다음이죠."),
(MT, "Soprattutto le banche fiorentine.", "피렌체 은행은 특히 그렇고요."),
(E, "(firma un modulo) Va bene. Lunedì l'importo è disponibile. Dottor Corsini, un'ultima cosa, da persona e non da banca.", "(서류에 서명하며) 좋아요. 월요일에 금액이 들어갈 거예요. 코르시니 씨, 마지막으로 하나, 은행 말고 사람으로서요."),
(F, "Mi dica.", "말씀하세요."),
(E, "Ha l'aria stanca. Le aziende che vanno bene a volte stancano più di quelle che vanno male.", "피곤해 보이세요. 잘되는 회사가 가끔은 안되는 회사보다 사람을 더 지치게 하거든요."),
(F, "(sorride appena) Lo dirò a mia madre. Le piacerà.", "(희미하게 웃으며) 어머니께 전할게요. 좋아하실 거예요."),
(None, "Nel parcheggio, l'asfalto scotta. Filippo apre la macchina e resta in piedi accanto alla portiera.", "주차장 아스팔트가 뜨겁다. 필리포는 차 문을 열고 문 옆에 선 채로 있다."),
(MT, "Fatto. Visto? Il marchio si ripaga la pelle. Lo vedrai a settembre.", "됐다. 봤지? 브랜드는 자기 가죽값을 갚아. 9월에 보게 될 거야."),
(F, "Matteo, ascoltami bene. Questa è l'ultima volta.", "마테오, 잘 들어. 이번이 마지막이야."),
(MT, "L'ultima volta di cosa?", "뭐가 마지막인데?"),
(F, "L'ultima volta che i soldi della Maison pagano la pelle del marchio. Stamattina ho caricato tremila borse con il nome di un altro sopra. Quelle borse pagano tutto: gli stipendi, la luce, e adesso anche il tuo grigio verde.", "메종 돈이 브랜드 가죽값을 대는 거 말이야. 오늘 아침 난 남의 이름이 붙은 가방 3,000개를 실었어. 그 가방들이 다 내. 월급도, 전기료도, 이제 네 회녹색까지."),
(MT, "E a settembre il grigio verde le restituirà. Con gli interessi.", "그리고 9월에 그 회녹색이 다 갚아. 이자까지 쳐서."),
(F, "Speriamo. Ma se a settembre non torna, da ottobre il marchio vive dei suoi soldi. Tanto vale dirlo adesso, così nessuno si offende dopo.", "그러길 바라자. 근데 9월에 안 돌아오면 10월부터 브랜드는 자기 돈으로 사는 거야. 차라리 지금 말해 두는 게 나아. 나중에 아무도 서운해하지 않게."),
(MT, "Lo dici come se il marchio fosse un altro. È nostro, Filippo. È tuo anche lui.", "브랜드가 남의 것처럼 말하네. 우리 거야, 형. 형 것이기도 해."),
(F, "Lo so che è mio. È per questo che ho paura.", "내 거인 줄 알아. 그래서 무서운 거야."),
(None, "Matteo apre la bocca per rispondere, poi la richiude. Salgono in macchina. Per tutto il viaggio verso Scandicci la radio resta spenta.", "마테오가 대꾸하려고 입을 열었다가 다시 다문다. 둘은 차에 탄다. 스칸디치로 돌아가는 내내 라디오는 꺼져 있다."),

("#", "Scena 4 — Ore 20.15. Il laboratorio vuoto.", "장면 4 — 저녁 8시 15분. 텅 빈 공방."),
(None, "Gli operai sono usciti. Sul banco del controllo, le schede della « seconda mano » appese a una molletta. Chiara sta tagliando una sagoma di carta. Filippo entra senza accendere le luci grandi.", "직원들은 퇴근했다. 검사대 위에는 '두 번째 손' 점검표가 집게에 걸려 있다. 키아라가 종이 본을 자르고 있다. 필리포가 큰 불을 켜지 않고 들어온다."),
(C, "Ancora qui? Pensavo fossi già a casa con Giulia.", "아직 있어? 벌써 줄리아랑 집에 간 줄 알았는데."),
(F, "Giulia è al mare con le amiche. Casa è vuota. Anche qui, ma qui fa meno rumore.", "줄리아는 친구들이랑 바다에 갔어. 집이 비었어. 여기도 비었지만, 여긴 덜 시끄러워."),
(C, "Matteo mi ha detto della conceria. E della banca. E dell'« ultima volta ».", "마테오가 무두질 공장 얘기 해 줬어. 은행 얘기도. 그리고 '마지막' 얘기도."),
(F, "Era arrabbiato?", "화났어?"),
(C, "Più che arrabbiato, offeso. Ma ha messo il tuo foglio del mese in bacheca, in ufficio. Con i numeri di oggi, senza aggettivi. Come vuoi tu.", "화났다기보다 서운해했어. 근데 사무실 게시판에 오빠가 원하는 월간 한 장 보고서를 붙여 놨어. 오늘 숫자로, 형용사 없이. 오빠가 원하는 대로."),
(F, "(si avvicina al banco, guarda la sagoma) Cos'è?", "(작업대로 다가가 본을 보며) 이게 뭐야?"),
(C, "La Ponte. La versione per la Corea. Cento grammi in meno, tracolla regolabile. Il grigio verde ci starà bene.", "'폰테'. 한국 버전. 100그램 가볍고, 끈은 조절식. 회녹색이 잘 어울릴 거야."),
(F, "Chiara, tu hai paura?", "키아라, 너는 무서워?"),
(C, "(smette di tagliare) Di cosa?", "(자르던 손을 멈추며) 뭐가?"),
(F, "Che man mano che il marchio cresce, la Maison diventi un'altra cosa. Una cosa che non ci serve più. E che un giorno ci chiami per dirci che non le serviamo più noi.", "브랜드가 커 갈수록 메종이 다른 게 되는 거. 우리한테 필요 없는 무언가가 되는 거. 그리고 어느 날 메종이 전화해서 이제 우리가 필요 없다고 말하는 거."),
(C, "Ho paura dal duemilaquindici, Filippo. Tu hai cominciato oggi. Benvenuto.", "난 2015년부터 무서웠어, 오빠. 오빠는 오늘 시작한 거고. 환영해."),
(F, "(ride piano, per la prima volta nella giornata) Me lo sono meritato.", "(하루 중 처음으로 나지막이 웃으며) 그 말 들어도 싸지."),
(C, "Te lo sei meritato. Ma ascolta anche questa: la paura non è un piano. È solo un rumore.", "들어도 싸지. 근데 이것도 들어 봐. 두려움은 계획이 아니야. 그냥 소음이야."),
(F, "E il piano qual è?", "그럼 계획은 뭔데?"),
(C, "Il piano è che la Ponte pesi cento grammi in meno e arrivi a Seul prima del quindici settembre. E che tu, a settembre, guardi il foglio di Matteo senza decidere prima di averlo letto.", "계획은 '폰테'가 100그램 가볍고 9월 15일 전에 서울에 도착하는 거. 그리고 오빠가 9월에 마테오 보고서를 읽기 전에 결정하지 않는 거."),
(F, "Questo è più difficile della Ponte.", "그게 '폰테'보다 어렵네."),
(C, "Lo so. Per questo te lo dico adesso.", "알아. 그래서 지금 말하는 거야."),
(F, "Va bene. Leggo prima. Decido dopo.", "알았어. 먼저 읽고, 나중에 결정할게."),
(C, "E stasera dormi. Hai la faccia del babbo quando tornava da Parigi.", "그리고 오늘 밤엔 자. 아빠가 파리에서 돌아올 때 얼굴이야."),
(F, "Grazie, Chiara. Davvero.", "고마워, 키아라. 진심이야."),
(C, "Vai a casa. Domani è sabato. E sabato non si parla di soldi, l'ha detto la mamma.", "집에 가. 내일 토요일이야. 토요일엔 돈 얘기 안 하는 거라고 엄마가 그랬잖아."),
(F, "La mamma dice tante cose.", "엄마는 말을 많이 하시지."),
(C, "E di solito ha ragione. Buonanotte, direttore.", "그리고 대개는 맞는 말이지. 잘 자, 사장님."),
(None, "Filippo esce. Chiara riprende le forbici, poi si ferma e guarda la porta che si è appena chiusa. Sul suo telefono, una notifica dalla chat di famiglia « Corsini a tavola »: Matteo ha scritto soltanto « Fatto. Grazie. »", "필리포가 나간다. 키아라는 다시 가위를 들었다가 멈추고 방금 닫힌 문을 바라본다. 휴대폰에 가족 채팅방 'Corsini a tavola' 알림이 뜬다. 마테오가 쓴 건 단 한 줄, '됐어. 고마워.'"),
]

